// ------------------------------------------------------------
// 1. OCR-Fehler in UIDs korrigieren (VOR dem cleanVat-Schritt)
// ------------------------------------------------------------

const correctOcrUid = (uid) => {
  if (!uid || uid === "LEER" || uid === "NICHT_LESBAR") return uid;

  uid = uid.toUpperCase().replace(/\s+/g, "");

  const prefix = uid.substring(0, 2);
  let digits = uid.substring(2);

  digits = digits
    .replace(/O/g, "0")
    .replace(/I/g, "1")
    .replace(/L/g, "1")
    .replace(/B/g, "8")
    .replace(/S/g, "5")
    .replace(/G/g, "6")
    .replace(/Z/g, "2")
    .replace(/T/g, "7");

  if (prefix === "AT") {
    if (!digits.startsWith("U")) {
      digits = "U" + digits.replace(/^U?/, "");
    }
    const nummer = digits.substring(1);
    if (nummer.length !== 8 || !/^\d+$/.test(nummer)) {
      return "NICHT_LESBAR";
    }
  }

  return prefix + digits;
};

// ------------------------------------------------------------
// 2. UID bereinigen
// ------------------------------------------------------------

const cleanVat = (vatString) => {
  if (!vatString || vatString === "LEER" || vatString === "NICHT_LESBAR") return "LEER";
  let cleaned = vatString.replace(/\s+/g, "").toUpperCase();
  if (cleaned.length > 15) return "LEER";
  return cleaned;
};

// ------------------------------------------------------------
// 3. IBAN bereinigen (OCR Fehler korrigieren)
// ------------------------------------------------------------

const cleanIban = (iban) => {
  if (!iban || iban === "LEER") return "LEER";

  iban = iban.toUpperCase().replace(/\s+/g, "");

  if (iban.includes("X") || iban.includes("*")) return "LEER";

  const prefix = iban.substring(0, 2);
  const rest = iban
    .substring(2)
    .replace(/O/g, "0")
    .replace(/I/g, "1")
    .replace(/S/g, "5");

  return prefix + rest;
};

// ------------------------------------------------------------
// 4. UID über EU VIES prüfen
// ------------------------------------------------------------

const checkVat = async (vatString) => {
  if (!vatString || vatString === "LEER" || vatString.length < 5) {
    return { valid: true, skipped: true };
  }

  if (vatString.toUpperCase().startsWith("EU")) {
    return { valid: true, skipped: true };
  }

  const country = vatString.substring(0, 2).toUpperCase();
  const number = vatString.substring(2).replace(/[^0-9A-Z]/g, "");

  if (!country || !number) {
    return { valid: true, skipped: true };
  }

  try {
    const response = await fetch(
      `https://ec.europa.eu/taxation_customs/vies/rest-api/ms/${country}/vat/${number}`
    );
    if (!response.ok) return { valid: true, skipped: true };
    const data = await response.json();
    return { valid: data.isValid, skipped: false };
  } catch (e) {
    return { valid: true, skipped: true };
  }
};

// ------------------------------------------------------------
// 5. IBAN mathematisch prüfen (Modulo 97)
// ------------------------------------------------------------

function isValidIBAN(iban) {
  if (!iban || iban === "LEER") return true;

  iban = iban.replace(/\s+/g, "").toUpperCase();

  if (!/^([A-Z]{2})(\d{2})([A-Z\d]+)$/.test(iban)) return false;
  if (iban.length < 15 || iban.length > 34) return true;

  const rearranged = iban.substring(4) + iban.substring(0, 4);

  const numeric = rearranged
    .split("")
    .map((c) => {
      const code = c.charCodeAt(0);
      return code >= 65 && code <= 90 ? (code - 55).toString() : c;
    })
    .join("");

  let remainder = numeric;
  while (remainder.length > 2) {
    const block = remainder.slice(0, 9);
    remainder = (parseInt(block, 10) % 97) + remainder.slice(block.length);
  }

  return parseInt(remainder, 10) % 97 === 1;
}

// ------------------------------------------------------------
// INPUT BEREINIGEN
// ------------------------------------------------------------

const rawAbsenderVat = correctOcrUid(inputData.uid_absender);
const rawEmpfaengerVat = correctOcrUid(inputData.uid_empfaenger);

const absenderVat = cleanVat(rawAbsenderVat);
const empfaengerVat = cleanVat(rawEmpfaengerVat);
const gefundeneIban = cleanIban(inputData.iban);

let final_status = inputData.status;
let ablehnungsgrund = inputData.grund || "Keiner";
let benachrichtigung = "INFO_AN_BUCHHALTUNG";

const text = (inputData.dokumenttext || "").toLowerCase();
const grundText = (inputData.grund || "").toLowerCase();
const absenderText = (inputData.absender || "").toLowerCase();

// Hinweise und IBAN-Warnung vorab initialisieren
let hinweise = [];
let iban_warnung = false;

// ------------------------------------------------------------
// 6. BEHÖRDEN AUTOMATISCH FREIGEBEN
// ------------------------------------------------------------

if (
  grundText.includes("behörde") ||
  absenderText.includes("stadt wien") ||
  absenderText.includes("finanzamt") ||
  absenderText.includes("magistrat") ||
  absenderText.includes("gericht") ||
  absenderText.includes("wirtschaftskammer") ||
  absenderText.includes("wko") ||
  absenderText.includes("sozialversicherung") ||
  absenderText.includes("ögk") ||
  absenderText.includes("svs")
) {
  return {
    final_status: "GÜLTIG",
    ablehnungsgrund: "Behörde",
    benachrichtigung: "NORMAL",
    geprüfte_iban: gefundeneIban
  };
}

// ------------------------------------------------------------
// 7. INTERNE ABRECHNUNGEN (Spesen / Strom / Wallbox)
// ------------------------------------------------------------

if (
  text.includes("abrechnung") &&
  (
    text.includes("stromkosten") ||
    text.includes("spesen") ||
    text.includes("kostenersatz") ||
    text.includes("wallbox") ||
    text.includes("zählerstand") ||
    text.includes("e-auto")
  )
) {
  return {
    final_status: "GÜLTIG",
    ablehnungsgrund: "Interne Abrechnung / Kostenersatz",
    benachrichtigung: "NORMAL",
    geprüfte_iban: gefundeneIban
  };
}
// Redlinghofer → eigener Path
if (grundText.includes("redlinghofer")) {
  return {
    final_status: "UNGÜLTIG",
    ablehnungsgrund: "Redlinghofer",
    benachrichtigung: "REDLINGHOFER",
    geprüfte_iban: gefundeneIban,
    uid_hinweis: "",
    kreditkarten_monat: "00",
    kreditkarten_jahr: "0000"
  };
}
// ------------------------------------------------------------
// 8. NORMALE RECHNUNGSPRÜFUNG
// ------------------------------------------------------------

if (final_status === "GÜLTIG") {

  let hatHartenFehler = false;

  // Absender-UID prüfen (nur wenn vorhanden)
  if (absenderVat !== "LEER") {
    const absenderCheck = await checkVat(absenderVat);

    if (absenderCheck.valid === false && absenderCheck.skipped === false) {

      const absenderName = (inputData.absender || "").toLowerCase();
      const istErkennbareFirma =
        absenderName.includes("gmbh") ||
        absenderName.includes("gesmbh") ||
        absenderName.includes(" ag") ||
        absenderName.includes(" kg") ||
        absenderName.includes(" og") ||
        absenderName.includes("e.u.") ||
        absenderName.includes("gmbh & co");

      if (istErkennbareFirma) {
        hinweise.push("UID ungueltig - bitte manuell pruefen");
        benachrichtigung = "INFO_AN_BUCHHALTUNG";
        // final_status bleibt GÜLTIG

      } else {
        final_status = "UNGÜLTIG";
        ablehnungsgrund =
          "Die UID-Nummer des Absenders (" +
          absenderVat +
          ") ist laut der europäischen VIES-Datenbank ungültig oder inaktiv. Bitte Rechnung prüfen und korrigieren.";
        benachrichtigung = "MAIL_AN_FIRMA";
        hatHartenFehler = true;
      }
    }
  }

  // Empfänger-UID prüfen (nur wenn vorhanden UND kein vorheriger Fehler)
  if (!hatHartenFehler && empfaengerVat !== "LEER") {
    const empfaengerCheck = await checkVat(empfaengerVat);

    if (empfaengerCheck.valid === false && empfaengerCheck.skipped === false) {
      final_status = "UNGÜLTIG";
      ablehnungsgrund =
        "Achtung: Der Lieferant hat eine ungültige oder falsche Empfänger-UID (" +
        empfaengerVat +
        ") von uns auf die Rechnung gedruckt!";
      benachrichtigung = "INFO_AN_BUCHHALTUNG";
      hatHartenFehler = true;
    }
  }

  // IBAN prüfen (nur Warnung, blockiert NICHT)
  if (!hatHartenFehler && gefundeneIban && gefundeneIban !== "LEER") {
    const is_iban_valid = isValidIBAN(gefundeneIban);
    if (is_iban_valid === false) {
      iban_warnung = true;
    }
  }

}

// ------------------------------------------------------------
// 9. HINWEISE FÜR STEMPEL
// ------------------------------------------------------------

if (inputData.uid_absender === "NICHT_LESBAR" || rawAbsenderVat === "NICHT_LESBAR") {
  hinweise.push("UID nicht lesbar - bitte pruefen");
}

if (iban_warnung) {
  hinweise.push("IBAN fehlerhaft - bitte pruefen");
}

const uid_hinweis = hinweise.join(" | ");

// ------------------------------------------------------------
// 10. KREDITKARTEN-MONATSORDNER
// Bis 15. des Monats = aktueller Monat
// Ab 16. des Monats = nächster Monat
// ------------------------------------------------------------

const now = new Date();
const tag = now.getDate();
let monat = now.getMonth() + 1;
let jahr = now.getFullYear();

if (tag >= 16) {
  monat = monat + 1;
  if (monat > 12) {
    monat = 1;
    jahr = jahr + 1;
  }
}

const kreditkarten_monat = String(monat).padStart(2, "0");
const kreditkarten_jahr = String(jahr);

// ------------------------------------------------------------
// OUTPUT
// ------------------------------------------------------------

return {
  final_status: final_status,
  ablehnungsgrund: ablehnungsgrund,
  benachrichtigung: benachrichtigung,
  geprüfte_iban: gefundeneIban,
  uid_hinweis: uid_hinweis,
  kreditkarten_monat: kreditkarten_monat,
  kreditkarten_jahr: kreditkarten_jahr
};

